mapper.select:
SELECT e.id, e.type, e.scope, e.status, e.download_url, e.created_at, u.name AS operator
FROM export_job e
LEFT JOIN sys_user u ON u.id = e.operator_id
WHERE e.deleted = 0
ORDER BY ${sortColumn} ${sortDir}
LIMIT #{offset}, #{size}

mapper.update:
UPDATE export_job
SET status = 'FAILED', error_message = #{errorMessage}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, student_no, name, class_name, verify_code, used, created_at, updated_at FROM student_whitelist WHERE 1 = 1
AND used = #{used}
ORDER BY created_at ASC

SELECT l.id, l.created_at AS time, u.name AS operator, l.action, CONCAT_WS('/', l.target_type, l.target_id) AS target, l.detail, l.ip FROM operation_audit_log l LEFT JOIN sys_user u ON u.id = l.user_id WHERE 1 = 1
AND (l.action LIKE CONCAT('%', #{action}, '%') OR l.target_type LIKE CONCAT('%', #{action}, '%'))
AND u.name LIKE CONCAT('%', #{operator}, '%')
AND l.created_at >= #{from}
AND l.created_at <= #{to}
ORDER BY l.created_at ASC

SELECT id, request_id, user_ref, scene, model_name, prompt_version, duration_ms,
       status, token_estimate, request_hash, input_hash, created_at
FROM ai_call_log
WHERE 1 = 1

    AND scene = #{scene}


    AND status = #{status}


    AND created_at >= #{from}


    AND created_at <= #{to}

ORDER BY created_at ASC

SELECT id, name, path, status, sort_order, updated_at
FROM career_direction
WHERE deleted = 0

    AND path = #{path}


    AND status = #{status}

ORDER BY sort_order ASC, id ASC

SELECT u.student_no, p.name, p.class_name, p.grade, p.major_category, p.completeness, p.development_intention AS path, EXISTS(SELECT 1 FROM assessment_session s WHERE s.student_id = u.id AND s.status = 'SCORED') AS assessed, (SELECT g.name FROM student_goal g WHERE g.student_id = u.id AND g.goal_type = 'PRIMARY' AND g.status = 'ACTIVE' LIMIT 1) AS primary_goal, (SELECT MAX(r.submitted_at) FROM stage_review r WHERE r.student_id = u.id AND r.status = 'SUBMITTED') AS last_review FROM sys_user u JOIN student_profile p ON p.user_id = u.id WHERE u.deleted = 0 AND u.role = 'STUDENT'
AND p.class_name = #{className}
AND p.grade = #{grade}
ORDER BY u.id ASC

SELECT id, created_at AS time, user_ref, scene, model_name, prompt_version, duration_ms,
       status, token_estimate, request_hash
FROM ai_call_log
WHERE 1 = 1

    AND scene = #{scene}


    AND status = #{status}


    AND created_at >= #{from}


    AND created_at <= #{to}

ORDER BY ${sortColumn} ${sortDir}
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM ai_call_log
WHERE 1 = 1

    AND scene = #{scene}


    AND status = #{status}


    AND created_at >= #{from}


    AND created_at <= #{to}

SELECT l.id, l.created_at AS time, u.name AS operator, l.action,
       CONCAT_WS('/', l.target_type, l.target_id) AS target,
       l.detail, l.ip
FROM operation_audit_log l
LEFT JOIN sys_user u ON u.id = l.user_id
WHERE 1 = 1

    AND (l.action LIKE CONCAT('%', #{action}, '%') OR l.target_type LIKE CONCAT('%', #{action}, '%'))


    AND u.name LIKE CONCAT('%', #{operator}, '%')


    AND l.created_at >= #{from}


    AND l.created_at <= #{to}

ORDER BY ${sortColumn} ${sortDir}
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM operation_audit_log l LEFT JOIN sys_user u ON u.id = l.user_id WHERE 1 = 1
AND (l.action LIKE CONCAT('%', #{action}, '%') OR l.target_type LIKE CONCAT('%', #{action}, '%'))
AND u.name LIKE CONCAT('%', #{operator}, '%')
AND l.created_at >= #{from}
AND l.created_at <= #{to}
